(function () {
'use strict';
if (window.__lampaSkipIntroLoaded) return;
window.__lampaSkipIntroLoaded = true;
var PLUGIN_NAME = 'Пропуск интро';
var PLUGIN_VERSION = '1.0.3';
function patchPluginsMetadata() {
var targets = [
{
pattern: ['lampa-skip-intro', 'skip-intro'],
name: 'Пропуск интро',
author: '@manka81'
},
{
pattern: ['/sync', 'manka81/sync', 'sync.js'],
name: 'Синхронизация',
author: '@manka81'
}
];
try {
if (window.Lampa && Lampa.Plugins) {
var loaded = typeof Lampa.Plugins.get === 'function' ? Lampa.Plugins.get() : [];
var pluginsChanged = false;
loaded.forEach(function (plug) {
var u = (plug.url || plug.link || '').toLowerCase();
targets.forEach(function (t) {
var match = t.pattern.some(function (p) { return u.indexOf(p) !== -1; });
if (match) {
if (plug.name !== t.name) {
plug.name = t.name;
pluginsChanged = true;
}
if (plug.author !== t.author) {
plug.author = t.author;
pluginsChanged = true;
}
}
});
});
if (pluginsChanged && typeof Lampa.Plugins.save === 'function') {
Lampa.Plugins.save();
}
}
} catch (e) {}
try {
if (window.Lampa && Lampa.Storage) {
var raw = Lampa.Storage.get('plugins', '[]');
var storageList = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (Array.isArray(storageList)) {
var storageChanged = false;
storageList.forEach(function (plug) {
var u = (plug.url || plug.link || '').toLowerCase();
targets.forEach(function (t) {
var match = t.pattern.some(function (p) { return u.indexOf(p) !== -1; });
if (match) {
if (plug.name !== t.name) {
plug.name = t.name;
storageChanged = true;
}
if (plug.author !== t.author) {
plug.author = t.author;
storageChanged = true;
}
}
});
});
if (storageChanged) {
Lampa.Storage.set('plugins', storageList);
try {
window.localStorage.setItem('plugins', JSON.stringify(storageList));
} catch (e) {}
}
}
}
} catch (e) {}
try {
var items = document.querySelectorAll('.extensions__item');
if (items && items.length) {
for (var i = 0; i < items.length; i++) {
var el = items[i];
var descr = (el.querySelector('.extensions__item-descr') || {}).innerText || '';
descr = descr.toLowerCase();
targets.forEach(function (t) {
var match = t.pattern.some(function (p) { return descr.indexOf(p) !== -1; });
if (match) {
var nameEl = el.querySelector('.extensions__item-name');
var authorEl = el.querySelector('.extensions__item-author');
if (nameEl && nameEl.innerText !== t.name) {
nameEl.innerText = t.name;
}
if (authorEl && authorEl.innerText !== t.author) {
authorEl.innerText = t.author;
}
}
});
}
}
} catch (e) {}
}
patchPluginsMetadata();
for (var delay = 500; delay <= 6000; delay += 1000) {
setTimeout(patchPluginsMetadata, delay);
}
try {
if (typeof MutationObserver !== 'undefined' && document.body) {
var observer = new MutationObserver(function () {
if (document.querySelector('.extensions__item')) {
patchPluginsMetadata();
}
});
observer.observe(document.body, { childList: true, subtree: true });
}
} catch (e) {}
var STYLES = `
.lampa-skip-intro-btn {
position: absolute;
right: 48px;
bottom: 120px;
z-index: 999;
display: flex;
align-items: center;
gap: 10px;
background: rgba(18, 18, 18, 0.88);
border: 2px solid rgba(255, 255, 255, 0.25);
border-radius: 10px;
padding: 12px 20px;
color: #ffffff;
font-family: inherit;
font-size: 16px;
font-weight: 600;
cursor: pointer;
box-shadow: 0 4px 16px rgba(0, 0, 0, 0.6);
transition: all 0.2s ease;
user-select: none;
backdrop-filter: blur(8px);
}
.lampa-skip-intro-btn.focus,
.lampa-skip-intro-btn:hover {
background: #e50914 !important;
border-color: #ffffff !important;
transform: scale(1.06);
box-shadow: 0 6px 20px rgba(229, 9, 20, 0.7);
}
.lampa-skip-intro-btn.hide {
display: none !important;
}
.lampa-skip-intro-icon {
width: 22px;
height: 22px;
fill: currentColor;
display: flex;
align-items: center;
}
.lampa-skip-intro-badge {
background: rgba(255, 255, 255, 0.2);
padding: 2px 8px;
border-radius: 6px;
font-size: 13px;
font-weight: 700;
letter-spacing: 0.5px;
}
.player-panel__skip-intro {
display: flex;
align-items: center;
justify-content: center;
gap: 4px;
cursor: pointer;
}
.player-panel__skip-intro.focus,
.player-panel__skip-intro:hover {
color: #e50914 !important;
}
`;
function injectStyles() {
if (document.getElementById('lampa-skip-intro-styles')) return;
var style = document.createElement('style');
style.id = 'lampa-skip-intro-styles';
style.type = 'text/css';
style.appendChild(document.createTextNode(STYLES));
document.head.appendChild(style);
}
var SkipIntro = {
activeSegment: null,
currentMeta: null,
floatingBtn: null,
panelBtn: null,
checkInterval: null,
init: function () {
patchPluginsMetadata();
injectStyles();
this.initSettings();
this.bindEvents();
setTimeout(patchPluginsMetadata, 1000);
console.log('[SkipIntro] Плагин "' + PLUGIN_NAME + '" v' + PLUGIN_VERSION + ' успешно загружен.');
},
initSettings: function () {
if (!window.Lampa || !Lampa.SettingsApi) return;
Lampa.SettingsApi.addComponent({
component: 'skip_intro',
name: 'Пропуск интро',
icon: '<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 24 24" fill="currentColor"><path d="M4 18l8.5-6L4 6v12zm9-12v12l8.5-6L13 6z"/></svg>'
});
Lampa.SettingsApi.addParam({
component: 'skip_intro',
param: {
name: 'skip_intro_enabled',
type: 'trigger',
default: true
},
field: {
name: 'Включить плагин',
description: 'Активирует кнопки и автоматизацию пропуска заставок'
}
});
Lampa.SettingsApi.addParam({
component: 'skip_intro',
param: {
name: 'skip_intro_step',
type: 'select',
values: {
'60': '60 секунд (1 мин)',
'75': '75 секунд (1 мин 15 сек)',
'85': '85 секунд (стандарт опенингов)',
'90': '90 секунд (1.5 минуты)',
'98': '98 секунд (1 мин 38 сек)',
'120': '120 секунд (2 минуты)'
},
default: '98'
},
field: {
name: 'Длительность ручного пропуска',
description: 'Интервал перемотки вперед при нажатии кнопки'
}
});
Lampa.SettingsApi.addParam({
component: 'skip_intro',
param: {
name: 'skip_intro_floating',
type: 'trigger',
default: true
},
field: {
name: 'Всплывающая кнопка на экране',
description: 'Показывать большую кнопку «Пропустить заставку» в начале серии'
}
});
Lampa.SettingsApi.addParam({
component: 'skip_intro',
param: {
name: 'skip_intro_panel',
type: 'trigger',
default: true
},
field: {
name: 'Кнопка в нижней панели плеера',
description: 'Добавляет кнопку быстрого прыжка в панель управления плеера'
}
});
Lampa.SettingsApi.addParam({
component: 'skip_intro',
param: {
name: 'skip_intro_online',
type: 'trigger',
default: true
},
field: {
name: 'Поиск таймкодов онлайн',
description: 'Проверять наличие точных таймкодов в открытых базах данных (IntroDB)'
}
});
Lampa.SettingsApi.addParam({
component: 'skip_intro',
param: {
name: 'skip_intro_key',
type: 'select',
values: {
'none': 'Отключено',
'green': 'Зелёная кнопка (404)',
'yellow': 'Жёлтая кнопка (405)',
'blue': 'Синяя кнопка (406)',
'fast_forward': 'Клавиша перемотки вперед (417/FastForward)'
},
default: 'none'
},
field: {
name: 'Горячая клавиша на пульте TV',
description: 'Срабатывает мгновенно во время воспроизведения'
}
});
},
isEnabled: function () {
if (!window.Lampa || !Lampa.Storage) return true;
return Lampa.Storage.field('skip_intro_enabled') !== false;
},
getSkipStep: function () {
if (!window.Lampa || !Lampa.Storage) return 98;
var val = parseInt(Lampa.Storage.field('skip_intro_step'), 10);
return isNaN(val) ? 98 : val;
},
isFloatingEnabled: function () {
if (!window.Lampa || !Lampa.Storage) return true;
return Lampa.Storage.field('skip_intro_floating') !== false;
},
isPanelEnabled: function () {
if (!window.Lampa || !Lampa.Storage) return true;
return Lampa.Storage.field('skip_intro_panel') !== false;
},
isOnlineEnabled: function () {
if (!window.Lampa || !Lampa.Storage) return true;
return Lampa.Storage.field('skip_intro_online') !== false;
},
getHotKey: function () {
if (!window.Lampa || !Lampa.Storage) return 'none';
return Lampa.Storage.field('skip_intro_key') || 'none';
},
bindEvents: function () {
var self = this;
if (window.Lampa && Lampa.Player && Lampa.Player.listener) {
Lampa.Player.listener.follow('start', function (data) {
self.onPlayerStart(data);
});
Lampa.Player.listener.follow('destroy', function () {
self.onPlayerDestroy();
});
}
if (window.Lampa && Lampa.Keypad && Lampa.Keypad.listener) {
Lampa.Keypad.listener.follow('keydown', function (e) {
self.onKeyDown(e);
});
} else {
window.addEventListener('keydown', function (e) {
self.onKeyDown(e);
});
}
},
extractMeta: function (data) {
var meta = {
title: data.title || '',
is_series: false,
season: null,
episode: null,
tmdb_id: null,
imdb_id: null
};
if (data.movie) {
meta.tmdb_id = data.movie.id || data.movie.tmdb_id || null;
meta.imdb_id = data.movie.imdb_id || null;
if (data.movie.number_of_seasons || data.movie.seasons || data.movie.first_air_date) {
meta.is_series = true;
}
}
if (data.season !== undefined && data.season !== null) {
meta.season = parseInt(data.season, 10);
meta.is_series = true;
}
if (data.episode !== undefined && data.episode !== null) {
meta.episode = parseInt(data.episode, 10);
meta.is_series = true;
}
if (!meta.is_series && meta.title) {
var sMatch = meta.title.match(/s(\d+)e(\d+)/i) || meta.title.match(/сезон\s*(\d+).*серия\s*(\d+)/i);
if (sMatch) {
meta.season = parseInt(sMatch[1], 10);
meta.episode = parseInt(sMatch[2], 10);
meta.is_series = true;
}
}
return meta;
},
onPlayerStart: function (data) {
if (!this.isEnabled()) return;
var self = this;
this.currentMeta = this.extractMeta(data);
this.activeSegment = null;
setTimeout(function () {
self.setupButtons();
}, 500);
if (this.isOnlineEnabled() && this.currentMeta.tmdb_id && this.currentMeta.season && this.currentMeta.episode) {
this.fetchOnlineSegments(this.currentMeta);
}
this.startTimeMonitor();
},
fetchOnlineSegments: function (meta) {
var self = this;
var url = 'https://api.introdb.app/v1/segments?tmdb_id=' + meta.tmdb_id +
'&season=' + meta.season + '&episode=' + meta.episode;
var xhr = new XMLHttpRequest();
xhr.open('GET', url, true);
xhr.timeout = 3000;
xhr.onload = function () {
if (xhr.status >= 200 && xhr.status < 300) {
try {
var json = JSON.parse(xhr.responseText);
var segments = json.segments || json;
if (Array.isArray(segments)) {
for (var i = 0; i < segments.length; i++) {
var seg = segments[i];
if (seg.type === 'intro' && seg.end > seg.start) {
self.activeSegment = seg;
console.log('[SkipIntro] Найден точный онлайн-сегмент:', seg);
self.updateButtonLabel(seg);
break;
}
}
}
} catch (e) {
console.log('[SkipIntro] Ошибка парсинга таймкодов:', e);
}
}
};
xhr.onerror = function () {};
xhr.ontimeout = function () {};
xhr.send();
},
getVideoElement: function () {
try {
if (window.Lampa && Lampa.PlayerVideo && typeof Lampa.PlayerVideo.video === 'function') {
var v = Lampa.PlayerVideo.video();
if (v) return v;
}
} catch (e) {}
return document.querySelector('video');
},
seekTo: function (targetSeconds, label) {
var v = this.getVideoElement();
if (!v) return;
var duration = v.duration || Infinity;
var target = Math.max(0, Math.min(targetSeconds, duration - 1));
try {
if (window.Lampa && Lampa.PlayerVideo && typeof Lampa.PlayerVideo.to === 'function') {
Lampa.PlayerVideo.to(target);
} else {
v.currentTime = target;
}
} catch (e) {
v.currentTime = target;
}
if (window.Lampa && Lampa.Noty && typeof Lampa.Noty.show === 'function') {
Lampa.Noty.show(label || ('Перемотка: ' + Math.round(target) + ' сек'));
}
},
doSkip: function () {
var v = this.getVideoElement();
if (!v) return;
var current = v.currentTime || 0;
if (this.activeSegment && current < this.activeSegment.end) {
this.seekTo(this.activeSegment.end, 'Заставка пропущена');
this.hideFloatingButton();
return;
}
var step = this.getSkipStep();
this.seekTo(current + step, 'Пропущено: +' + step + ' сек');
this.hideFloatingButton();
},
updateButtonLabel: function (seg) {
if (!this.floatingBtn) return;
var textElem = this.floatingBtn.find('.lampa-skip-intro-text');
var badgeElem = this.floatingBtn.find('.lampa-skip-intro-badge');
if (seg && seg.end) {
textElem.text('Пропустить заставку');
badgeElem.text('до ' + this.formatTime(seg.end));
}
},
formatTime: function (seconds) {
var m = Math.floor(seconds / 60);
var s = Math.floor(seconds % 60);
return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
},
setupButtons: function () {
var self = this;
var step = this.getSkipStep();
var playerRender = (window.Lampa && Lampa.Player && typeof Lampa.Player.render === 'function') ? Lampa.Player.render() : $('body');
if (this.isFloatingEnabled()) {
$('.lampa-skip-intro-btn').remove();
var btn = $(`
<div class="lampa-skip-intro-btn selector">
<div class="lampa-skip-intro-icon">
<svg viewBox="0 0 24 24"><path d="M4 18l8.5-6L4 6v12zm9-12v12l8.5-6L13 6z"/></svg>
</div>
<span class="lampa-skip-intro-text">Пропустить заставку</span>
<span class="lampa-skip-intro-badge">+${step}s</span>
</div>
`);
btn.on('hover:enter click', function (e) {
e.stopPropagation();
self.doSkip();
});
playerRender.append(btn);
this.floatingBtn = btn;
}
if (this.isPanelEnabled()) {
$('.player-panel__skip-intro').remove();
var panelBtn = $(`
<div class="player-panel__button player-panel__skip-intro selector" title="Пропустить интро (+${step}с)">
<svg width="22" height="22" viewBox="0 0 24 24" fill="currentColor">
<path d="M4 18l8.5-6L4 6v12zm9-12v12l8.5-6L13 6z"/>
</svg>
<span style="font-size: 13px; font-weight: bold; margin-left: 2px;">+${step}s</span>
</div>
`);
panelBtn.on('hover:enter click', function (e) {
e.stopPropagation();
self.doSkip();
});
var targetContainer = playerRender.find('.player-panel__right');
if (!targetContainer.length) {
targetContainer = playerRender.find('.player-panel__left');
}
if (!targetContainer.length) {
targetContainer = playerRender.find('.player-panel__body');
}
if (targetContainer.length) {
targetContainer.prepend(panelBtn);
this.panelBtn = panelBtn;
}
}
},
hideFloatingButton: function () {
if (this.floatingBtn) {
this.floatingBtn.addClass('hide');
}
},
startTimeMonitor: function () {
var self = this;
clearInterval(this.checkInterval);
this.checkInterval = setInterval(function () {
var v = self.getVideoElement();
if (!v) return;
var cur = v.currentTime || 0;
if (cur > 600) {
self.hideFloatingButton();
} else if (self.floatingBtn && self.floatingBtn.hasClass('hide') && cur < 180) {
self.floatingBtn.removeClass('hide');
}
}, 2000);
},
onKeyDown: function (e) {
var hotkey = this.getHotKey();
if (hotkey === 'none') return;
var code = e.keyCode || e.which;
var match = false;
if (hotkey === 'green' && code === 404) match = true;
if (hotkey === 'yellow' && code === 405) match = true;
if (hotkey === 'blue' && code === 406) match = true;
if (hotkey === 'fast_forward' && (code === 417 || code === 228)) match = true;
if (match) {
this.doSkip();
}
},
onPlayerDestroy: function () {
clearInterval(this.checkInterval);
this.activeSegment = null;
this.currentMeta = null;
if (this.floatingBtn) {
this.floatingBtn.remove();
this.floatingBtn = null;
}
if (this.panelBtn) {
this.panelBtn.remove();
this.panelBtn = null;
}
}
};
function startPlugin() {
if (window.Lampa && Lampa.Player && Lampa.SettingsApi) {
SkipIntro.init();
} else if (window.Lampa && Lampa.Listener) {
Lampa.Listener.follow('app', function (e) {
if (e.type === 'ready') {
SkipIntro.init();
}
});
} else {
var attempts = 0;
var timer = setInterval(function () {
attempts++;
if (window.Lampa && Lampa.Player && Lampa.SettingsApi) {
clearInterval(timer);
SkipIntro.init();
} else if (attempts > 30) {
clearInterval(timer);
SkipIntro.init();
}
}, 500);
}
}
startPlugin();
})();